function Lucky_AddMenu(&$m){    	 						
	global $zbp;    			 	   
	array_unshift($m, MakeTopMenu('root','Luckyä¸»é¢˜é…ç½®',$zbp->host . 'zb_users/theme/Lucky/config/main.php','','topmenu_Lucky'));       		 	 
