function Lucky_Host($url = '', $thumbnail = false, $thumbName = 0) {     		  		 
	global $zbp;     	   	  
	if ($zbp->Config('Lucky')->upyun == 'a') {    	 		 	 	
		$repOrUpyunUrl = $url ? str_replace($zbp->host.'zb_users/', $zbp->Config('upyun')->upyun_domain.'/zb_users/', $url) : $zbp->Config('upyun')->upyun_domain.'/';    			    	
		switch ($thumbName) {      		 		 
			case 1:    	 	 			 
				$verName = $zbp->Config('upyun')->upyun_ver_name_twitter;    	 		 		 
				break;      				 	
			default:    	  					
				$verName = $zbp->Config('upyun')->upyun_ver_name;    	 			   
				break;     	   		 
		}        			 
		$thumb = $thumbnail ? $zbp->Config('upyun')->upyun_cutname . $verName : '';    		 		 		
		$url = $repOrUpyunUrl.$thumb;        		 	
	} else {      	 			 
		$url = $url ?: $zbp->host;     	    		
	}     	   	 	
	return $url;    	 		    
}     				  	
      	 	 		
function Lucky_ConfigNav() {    	  		 	 
	global $zbp;        	  	
	$setUrl = array(     		     
		array('name' => 'åŸºæœ¬è®¾ç½®', 'pathname' => 'config.php'),    	 		    
		array('name' => 'å¹»ç¯è®¾ç½®', 'pathname' => 'slides.php'),    	 		 	 	
		array('name' => 'SEOè®¾ç½®', 'pathname' => 'seo.php'),    		 	   	
		array('name' => 'æ¨¡å—è®¾ç½®', 'pathname' => 'modules.php'),    	      	
		array('name' => 'ä¸Šä¼ è®¾ç½®', 'pathname' => 'upload.php'),     		   		
		array('name' => 'é¢œè‰²è®¾ç½®', 'pathname' => 'color.php'),    		  				
		array('name' => 'ä¿®å¤ä¸»é¢˜', 'pathname' => 'repair.php'),    	  	  	 
		array('name' => 'ä¸»é¢˜è¯´æ˜Ž', 'pathname' => 'main.php'),     		 	 		
	);     	 	  		
	$navigation = $title = '';       		  	
	$currentPathname = basename($zbp->fullcurrenturl);    	 	     
	foreach ($setUrl as $setVal) {    	   	 		
		$navigation .= '<li><a href="'.$setVal['pathname'].'">'.$setVal['name'].'</a></li>';    		      
		if (strpos($currentPathname, $setVal['pathname']) !== false) {    	 		    
			$title = $setVal['name'].' - Luckyä¸»é¢˜é…ç½®';     	 		 	 
		}     				   
	}    	   			 
	return array($navigation, $title);    		   		 
}      			 		
    	   	  	
