function Lucky_verify(){    	 		 			
	global $zbp;       	 	  
	if ($zbp->Config('Lucky')->geetest!="a") return true;      		  		
	if($zbp->option['ZC_COMMENT_VERIFY_ENABLE'] || GetVars('act', 'GET') !== 'cmt' || ($zbp->user->ID > 0 && $zbp->user->ID < 5)) {    				  		
		return;     	  		 	
	}    					  	
	$result = Lucky_verify_base();    				 	  
	if ($result == "ok") {    		  	 		
		return;    			   	 
	} else {    	  	 	 	
		ScriptError($result);    		    	 
	}    			 				
}    	 	   	 
    	  	 			
function Lucky_verify_base(){    		  		  
	global $zbp;         			
	if ($zbp->Config('Lucky')->geetest!="a") return true;      	     
	$zbp->StartSession();        		 	
	require_once 'function.php';          	 
	$GtSdk = new LuckyGeetestLib($zbp->Config('Lucky')->captcha_id, $zbp->Config('Lucky')->private_key);    		  	 	 
	if ($_SESSION['gtserver'] == 1) {      		 	 	
		$result = $GtSdk->success_validate($_COOKIE['geetestchallenge'], $_COOKIE['geetestvalidate'], $_COOKIE['geetestseccode']);        	 		
	} else {    	 					 
		$result = $GtSdk->fail_validate($_COOKIE['geetestchallenge'], $_COOKIE['geetestvalidate'], $_COOKIE['geetestseccode']);      	 			 
	}     	 				 
	return $result;    	 			   
}    	 	   	 
      		   	
function Lucky_CreateTable(){    	  					
    global $zbp;    	    	 	
    $sql=$zbp->db->sql->CreateTable($GLOBALS['Lucky_Table'],$GLOBALS['Lucky_DataInfo']);     		    	
    $zbp->db->QueryMulit($sql);      			 	 
}      						
    		 			 	
